// --- HOME (Updated with Real Backend Testimonials) ---
const Home = () => {
  const [testimonials, setTestimonials] = useState([]);
  const [newComment, setNewComment] = useState("");
  const [stars, setStars] = useState(5);
  const user = localStorage.getItem('username');

  // 1. Fetch les testimonials mn Django
  useEffect(() => {
    axios.get('http://127.0.0.1:8000/api/testimonials/')
      .then(res => setTestimonials(res.data))
      .catch(e => console.log(e));
  }, []);

  // 2. Fonction bach n-zido commentaire jdid
  const handleAddReview = async (e) => {
    e.preventDefault();
    const token = localStorage.getItem('token'); // Hna khdina l-token li khtiti f l-Login

    if (!token) {
      alert("❌ Vous devez être connecté pour laisser un avis !");
      return;
    }

    const config = {
      headers: { 'Authorization': `Bearer ${token}` }
    };

    const data = { content: newComment, stars: parseInt(stars) };

    try {
      const res = await axios.post('http://127.0.0.1:8000/api/testimonials/', data, config);
      setTestimonials([res.data, ...testimonials]); // Zid commentaire jdid l-foq
      setNewComment("");
      alert("✅ Avis ajouté avec succès !");
    } catch (err) {
      alert("❌ Erreur lors de l'envoi. Vérifiez votre connexion.");
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-white">
      {/* Hero Section (Khllitha kima hiya) */}
      <div className="relative h-[90vh] flex items-center justify-center overflow-hidden">
        <div className="absolute inset-0 z-0">
          <img src="https://images.unsplash.com/photo-1513104890138-7c749659a591?q=80&w=2070" className="w-full h-full object-cover" alt="Hero Background" />
          <div className="absolute inset-0 bg-black/60 backdrop-blur-[2px]"></div>
        </div>
        <div className="relative z-10 text-center px-6">
          <h1 className="text-7xl md:text-9xl font-black text-white mb-6 tracking-tighter italic drop-shadow-2xl">
            Fast<span className="text-orange-600">Délice</span>
          </h1>
          <p className="text-xl text-white mb-12 font-black italic max-w-xl mx-auto opacity-90">"La passion du goût, l'élégance du service."</p>
          <Link to="/menu" className="bg-orange-600 text-white px-14 py-5 rounded-full font-black uppercase text-sm tracking-widest hover:bg-white hover:text-orange-600 transition shadow-2xl inline-block">Commander Maintenant</Link>
        </div>
      </div>

      {/* Testimonials Section (White Background + Formulaire) */}
      <div className="bg-white py-24 px-6">
        <div className="max-w-7xl mx-auto">
          <div className="text-center mb-16">
            <h2 className="text-4xl font-black text-gray-900 italic uppercase tracking-tighter mb-4">Ce que nos clients disent</h2>
            <div className="h-1.5 w-20 bg-orange-600 mx-auto rounded-full"></div>
          </div>

          {/* Formulaire pour ajouter un avis (Seulement si connecté) */}
          {user && (
            <div className="max-w-2xl mx-auto mb-20 bg-gray-50 p-8 rounded-[2rem] border border-gray-100 shadow-sm">
              <h3 className="text-lg font-black uppercase italic mb-4 text-center">Partagez votre expérience</h3>
              <form onSubmit={handleAddReview} className="space-y-4">
                <textarea 
                  value={newComment}
                  onChange={(e) => setNewComment(e.target.value)}
                  placeholder="VOTRE MESSAGE..." 
                  className="w-full p-4 border rounded-xl outline-none focus:border-orange-600 font-bold italic"
                  required
                />
                <div className="flex justify-between items-center">
                  <select value={stars} onChange={(e) => setStars(e.target.value)} className="p-2 border rounded-xl font-bold bg-white">
                    <option value="5">⭐⭐⭐⭐⭐ (5/5)</option>
                    <option value="4">⭐⭐⭐⭐ (4/5)</option>
                    <option value="3">⭐⭐⭐ (3/5)</option>
                  </select>
                  <button type="submit" className="bg-orange-600 text-white px-8 py-3 rounded-xl font-black uppercase text-[10px] tracking-widest hover:bg-black transition">Envoyer l'avis</button>
                </div>
              </form>
            </div>
          )}

          {/* Affichage des commentaires depuis le Backend */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {testimonials.length > 0 ? testimonials.map((v, i) => (
              <div key={i} className="bg-gray-50 p-10 rounded-[3rem] border border-gray-100 hover:shadow-2xl transition-all duration-500 text-center group">
                <div className="text-orange-500 mb-6 text-sm tracking-[0.3em]">
                   {"★".repeat(v.stars)}{"☆".repeat(5-v.stars)}
                </div>
                <p className="text-gray-700 italic font-bold mb-8 text-lg leading-relaxed">"{v.content}"</p>
                <div className="flex flex-col items-center">
                  <div className="h-px w-10 bg-gray-200 mb-4 group-hover:w-20 transition-all"></div>
                  <span className="text-[10px] font-black text-orange-600 uppercase tracking-[0.2em]">— {v.user}</span>
                </div>
              </div>
            )) : (
              <p className="col-span-full text-center text-gray-400 italic">Aucun avis pour le moment.</p>
            )}
          </div>
        </div>
      </div>

      <footer className="bg-gray-50 py-8 border-t border-gray-100 text-center">
        <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.3em]">© 2026 FAST DÉLICE. TOUS DROITS RÉSERVÉS.</p>
      </footer>
    </div>
  );
};
